"""Render auditable experimental results from frozen raw outputs; no model selection."""
import json,pathlib,statistics,hashlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1]
ORDER=['N2-PA','prior160','prior170','prior190','old_SM-adaptiveprior','raw','corrected','masked','guided','full4','utilityprior','cf-gru']
def f(x,d=3):return 'NA' if x is None else f'{x:.{d}f}'
def table(t):
 out=['| 方法 | 产量 t/ha | NUE | 盈余 kg/ha | 联合达标 % | 盈余 CVaR10 | 提议违规 % | 执行违规 % |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for n in ORDER:
  p=t[n]['pooled'];out.append(f"| {n} | {f(p['yield_t_ha'])} | {f(p['NUE'])} | {f(p['surplus_kg_ha'])} | {f(100*p['joint'],2)} | {f(p['cvar10_surplus'])} | {f(100*p['proposed_violation_rate'],2)} | {f(100*p['executed_violation_rate'],2)} |")
 return '\n'.join(out)
def main():
 q=json.loads((R/'reports/final_cea_metrics.json').read_text());spl=q['heldout']['splits'];manifest=json.loads((R/'reports/heldout-unlock-manifest.json').read_text());lines=['# 精准施肥冻结实验结果','', '本报告是可复核的实验数据包，不是已完成的投稿稿件。所有结论限于当前 PCSE/WOFOST、固定初始氮基准和已登记气象序列。','', '## 核心结果','']
 for s,title in [('historical','历史 39 年 × 3 土壤'),('stress','压力 499 年 × 3 土壤')]:
  a=spl[s]['tables']['utilityprior']['pooled'];b=spl[s]['tables']['cf-gru']['pooled'];c=spl[s]['tables']['full4']['pooled'];cmp=spl[s]['comparisons']['utilityprior']['prior190']['joint_actual']
  lines.append(f"- {title}：森林主策略联合达标 {100*a['joint']:.2f}%，CF-GRU {100*b['joint']:.2f}%，Full4 {100*c['joint']:.2f}%；森林相对 prior190 的配对差为 {100*cmp['mean_difference']:+.2f} 个百分点，95% 年簇 bootstrap 区间 [{100*cmp['ci95'][0]:+.2f}, {100*cmp['ci95'][1]:+.2f}]，Wilcoxon p={cmp['wilcoxon_p']:.5g}。森林盈余 CVaR10={a['cvar10_surplus']:.3f} kg/ha。")
 lines+=['','历史总体差值区间跨零（p=.142），不能认定相对prior190的改善显著；压力总体改善约2.81个百分点（p=.0104），不是Dev中更强显著性的直接延续。原CEA default历史39年中，森林盈余CVaR10约65.09，高于prior190约57.85，表明聚合尾部风险改善不能推广到每一种土壤和年代。压力q25改善较明确，q10区间仍跨零。两个留出总体上CF-GRU点估计均未超过森林，神经残差没有形成可宣称的新增收益。','', 'CF-GRU 在预注册 Dev 联合达标点目标 ≥59.40% 上失败（实际59.2222%，差−0.1778个百分点）。其余要求的显著性、安全及CVaR检查通过。正式批准的A修订在盲测前将森林设为主策略、CF-GRU设为探索性残差变体；这是观察Dev后作出的主次调整，不能写成完全无Dev方法选择。没有因此更改权重、alpha、正则或阈值。原始失败门禁与批准文件均封存。CF对森林的Dev均值差bootstrap区间跨0，而Wilcoxon p=.0417，二者检验对象不同，不能声称均值区间排除零。','','## 数据、冻结与评估设计','',f"- 模型资产19个；神经方法 raw/corrected/masked/guided/full4/cf-gru 各3种子（4、17、29），森林1个拟合资产。森林种子别名不是3个独立重复。",f"- 最终评估完成{q['episodes']:,}个 method×seed×soil×year 季节。历史1983–2021：117个独立year-soil场景；压力5500–5998：1497个。default历史39年单列。",f"- 解锁清单SHA256：`{q['manifest_sha256']}`；事先Git提交：`{json.dumps(manifest['git_commits'],ensure_ascii=False)}`。",'- 原始任务中的阶段3C模式坍缩解释是待检验假说。本实验没有单独操纵隐藏初始氮或未来天气方差，不能将坍缩唯一归因于二者。Full4同时改变目标、GRU、弱二次先验、CVaR及在线3土壤DR，不能视作单因素消融。','- 所有拟合和超参数CV仅使用3002–4999训练年份；Dev5000–5499。配对网格360个year-soil场景×6剂量=2160季节。5折按年份分组，折内教师只拟合训练折，避免折内教师泄漏。','- 实体历史4×11与独立合法性掩码4×9拼为网络4×20；掩码不是额外传感器，所有实际氮池与未来天气均不进入actor。','- alpha=.05/.10/.05 是训练内CV后收缩；训练残差拟合使用alpha=1。所有折点效用不退化不意味着样本外保证，Dev短缺已如实保留。','- 成功的每季原始结果与日期/输入/动作记录均逐季封存JSON和SHA；中断只恢复已封存成功季节，不重算成功结果。它是防误改证据链，不是对恶意root的不可变存储。项目早期Phase2已做过同一历史/压力基准的其他审计；本次是冻结系列的一次最终评估，不能声称项目从未接触过这些基准。','- 压力年份是相同LARS气象生成体系中的预留序列，不代表已验证的灾害OOD分布或未来气候投影。','']
 lines+=['## 完整 Dev 矩阵','',table(q['Dev']['tables']),'']
 for s,title in [('historical','历史全土壤'),('historical_default_CEA2025','CEA原设置：default历史39年'),('stress','压力全土壤')]:lines += [f'## {title}','',table(spl[s]['tables']),'']
 lines+=['## 配对统计与干旱子集','','对每个year-soil先平均神经种子，再在同年内平均土壤。以年份为簇配对bootstrap 3000次，随机种子4；Wilcoxon双侧检验作用于同一配对年度差。CI是均值差区间，Wilcoxon检验分布位置，不能互相替代。CVaR是非可加尾部泛函，只做整年成簇的配对bootstrap，不伪造逐季CVaR的Wilcoxon。多指标、多比较均为未调整p值，应结合效应量和区间作探索性解释。完整产量/NUE/盈余/N投入/违规率及CVaR差与区间见JSON，不只筛选显著结果。','','| 数据子集 | 年数 | 方法 | 对照 | 联合差 pp | 95% CI pp | Wilcoxon p |','|---|---:|---|---|---:|---|---:|']
 cohorts={'Dev':q['Dev']};cohorts.update(spl)
 for s,item in cohorts.items():
  for n in ['utilityprior','cf-gru']:
   for ref,c in item['comparisons'][n].items():
    p=c['joint_actual'];ci=p['ci95'];lines.append(f"| {s} | {p['n_years']} | {n} | {ref} | {f(None if p['mean_difference'] is None else 100*p['mean_difference'],2)} | {'NA' if ci is None else '['+f(100*ci[0],2)+', '+f(100*ci[1],2)+']'} | {('NA' if p['wilcoxon_p'] is None else format(p['wilcoxon_p'],'.5g'))} |")
 th=q['heldout']['thresholds'];lines+=['',f"干旱阈值只由训练1998年Oct1–次年Jul31累计雨量确定：q10={th['q10_mm']:.3f} mm，q25={th['q25_mm']:.3f} mm。独立留出子集的实际样本数不强行等于10%或25%。",'', '| 子集 | 年数 | 森林达标 % | CF-GRU达标 % | Full4达标 % |','|---|---:|---:|---:|---:|']
 for s in ['historical_q10','historical_q25','stress_q10','stress_q25']:
  item=spl[s];vals=[]
  for n in ['utilityprior','cf-gru','full4']:vals.append('NA' if not item['tables'][n]['pooled']['n_episodes'] else f(100*item['tables'][n]['pooled']['joint'],2))
  lines.append(f"| {s} | {len(item['years'])} | "+' | '.join(vals)+' |')
 lines+=['','不足10年的子集给出small_n_caution；无场景则NA，不能将空子集当成零达标。','','## 与原论文表2的比较','','本地原文 `docs/compag2025rl.pdf`，Baja等，*Adaptive fertilizer management for optimizing nitrogen use efficiency with constrained reinforcement learning*，CEA237(2025)110554，DOI:10.1016/j.compag.2025.110554。按方法2.5.1采用1983–2021的39年。原文表2报告的是中位数：N2-PA产量9.61t/ha、NUE0.78、盈余52.6kg/ha；任务近似值9.605/.779/55.38未标明统计量；本次结果显示它们对应本次N2-PA的中位数，而不是均值。均值与中位数并列，不能混用。','','| 方法 | 产量均值/中位数 | NUE均值/中位数 | 盈余均值/中位数 |','|---|---:|---:|---:|']
 for n,rec in q['CEA2025_default_39'].items():
  vals=[f"{rec[k]['mean']:.3f} / {rec[k]['median']:.3f}" for k in ['yield_t_ha','NUE_actual','surplus_actual']];lines.append('| '+n+' | '+' | '.join(vals)+' |')
 n2=q['CEA2025_default_39']['N2-PA'];lines+=['',f"本次N2-PA均值相对任务近似值之差：产量{n2['yield_t_ha']['mean']-9.605:+.3f}t/ha、NUE{n2['NUE_actual']['mean']-.779:+.3f}、盈余{n2['surplus_actual']['mean']-55.38:+.3f}kg/ha。不据此反调模型或模拟配置。",f"本次N2-PA中位数为{n2['yield_t_ha']['median']:.6f}t/ha、{n2['NUE_actual']['median']:.6f}、{n2['surplus_actual']['median']:.6f}kg/ha，与任务近似值四舍五入一致；但盈余中位数比原文表2的52.6高{n2['surplus_actual']['median']-52.6:.3f}kg/ha，来源尚未单独归因，不能宣称表2全部数值精确复现。",'神经方法的均值和中位数池化三个冻结种子，独立历史年份仍为39（117个seed-year输出）；森林与N2-PA各为39个输出。原论文训练10种子×300万步并含E3B；本次每种子67200步且未复现整套E3B，因此是受控小预算基线，不宣称完整复现其RL结果。保留native_NUE/native_surplus/native_joint别名用于核对计量口径。','','## 归因案例与剂量适应性','',q['attribution_protocol'],'','案例按预留压力年份雨量极值确定，不按模型胜负挑选；不会额外运行环境。只读调用explain_decision，任何解释文本都不能回写动作。Shapley解释选中剂量的冻结模型效用分数，单位是效用分，不是kg/ha或真实因果贡献。','']
 for case in q['attribution']:
  row=case['episode'];lines.append(f"- {case['case']}，年份{case['year']}，土壤{case['soil']}，{case['policy']}：总N={row['actual_N']}kg/ha，产量={row['yield_t_ha']:.3f}t/ha，盈余={row['surplus_actual']:.3f}kg/ha，联合达标={row['joint_actual']}。")
  for d in case['decisions']:
   if .62<=d['DVS']<=.88:lines.append(f"  - 阶段3日期{d['application_date']}，SM={d['SM']:.3f}，LAI={d['LAI']:.3f}；提议/执行={d['proposed_kg_N_ha']:.0f}/{d['executed_kg_N_ha']:.0f}kg/ha；输入敏感性={json.dumps(d.get('shapley',{}),ensure_ascii=False)}。")
 lines+=['','压力分布实际总氮档位（不预设Full4必为190）：','']
 for k,v in q['dose_distribution'].items():lines.append(f"- {k}: "+', '.join(f'{n:g}kg/ha:{c}季' for n,c in zip(v['N'],v['counts'])))
 lines+=['','## 参数、训练与推理开销','','CF-GRU训练4908参数，实际actor计算2218参数（六档裁剪后2119）；2690参数用于训练辅助分支，前三个未部署输出行99参数仍参与正则。森林64树、37772冻结buffer元素，其结构容量不能称为零成本。原始4个PPO层级每模型4683参数，Full4每模型4908参数加森林buffer。实际文件字节见JSON。','','预算范围为本Phase4及本轮复用的已选Full4资产，不是整个项目从Phase1起的累计开发成本；更早阶段的失败/筛选训练不计入此小计，原始档案继续保留。2160标定季节本轮全部复用，其中原Phase3C新生成1260、从更早数据复用900；细节见phase4-budget-scope.json。','', '| 预算 | 数值 |','|---|---:|']+[f'| {k} | {v} |' for k,v in q['budgets'].items()]
 lines+=['','每种子CF15个CV神经拟合+1个最终拟合，各400梯度更新，共6400；3种子19200。2160季节为共享训练标定网格，不是额外PPO交互。旧corrected3模型因重复dual频次不一致，未读其Dev前以singledual重训，旧结果保留，额外201600步单列；不能隐藏为免费试错。训练墙钟为并发运行的各自elapsed，不能简单相加当独占CPU耗时。两轮共48季Dev控制器等价性核验和1季Train日期核验均不是拟合。','',q['benchmark_protocol'],'','| 方法/种子 | median ms/step | p95 ms/step | 文件bytes | 训练墙钟s |','|---|---:|---:|---:|---:|']
 for n,ss in q['overhead'].items():
  for seed,x in ss.items():lines.append(f"| {n}/{seed} | {f(x['median_ms'],4)} | {f(x['p95_ms'],4)} | {x['checkpoint_bytes']} | {f(x['training_wall_seconds_receipt'],2)} |")
 lines+=['','实际并行评估计时（与单线程微基准不同，含并发竞争）：','']
 for n,x in q['evaluation_runtime'].items():lines.append(f"- {n}: {x['inference_steps']}次决策，平均{x['mean_ms_per_decision']:.4f}ms/step。")
 lines+=['','森林拟合与配对网格模拟未保留可独立分离的墙钟收据，记为NA而非零；本次复用资产，未重新拟合。不将CF-GRU约18秒训练与2160次作物季节计算混为算法全成本。','','## 证据边界与局限','','- 各方法违规率按各自配置规则计算；未启用Shield的N2-PA/raw/corrected不能因此推断满足CUO的210kg预算、窗口和次数上限。实际14日施肥间距另按真实日期对全方法独立复核。','- 操作约束违规率为0仅表示施肥窗口/间距/次数/预算等已配置规则满足，联合NUE/盈余结果达标远非100%，不能叫作环境安全保证。每季另按实际施肥日期核查14日间距。','- 离线网格固定初始氮，PPO训练随机初始氮均值35、SD15，最终固定基准初始氮70。二者训练分布与信息条件不同，森林更接近评估初始条件，是比较局限。当前结果不能证明配对训练在所有随机初始化分布都占优。','- PPO低层历史1帧，Full4/CF4帧，另有森林先验容量和不同组合目标；这不是完全等容量的单模块因果实验。','- 归因替换部分观测可能产生分布外组合，因此只作模型敏感性，不作农学机制发现。理想化SM读数无传感器噪声；真实地块需要额外外部验证。','- 配对优势严格消去的是六动作共享的加性项；天气与剂量、土壤与剂量的交互仍然存在，不能声称全部未来天气或初始氮噪声都被抵消。配对真值来自同一模拟器，不等于田间随机试验中的因果识别。','- CV全折零退化是有限训练样本上的点估计，未提供普遍零退化保证。CF探索性变体未达到Dev点目标应继续写进正文和表格。','- 现有证据支持在当前模拟基准评价冻结策略；不支持直接推广生产部署、经济收益、气候韧性或真实田间因果结论。','','## 验证与复核入口','','- `reports/phase4-all-tests.xml`：71项，0失败、0错误、0跳过；包括配对优势、alpha0回退、梯度/保存加载、部署actor等价、清单封存与逐季篡改拒绝。','- `reports/phase4-controller-parity-final.json`：最终评估器24个Dev场景物理指标完全一致（另保留上一版本24季核验）；`reports/phase4-calendar-spacing-proof.json`：真实日期间距核验。','- `reports/phase4-review-final.md`：DeepSeek Flash/high第二轮冻结前只读审查；图件Gemini Carbon medium第二轮质检已接受，见phase4-figure-review.md；首轮五项呈现问题及原图在phase4-figure-review-round1.md和round0目录保留。','- `reports/heldout-unlock-manifest.json` / `.sha256`、`heldout-audit-claim.json`、`phase4-heldout-episodes/`：冻结与逐季审计。','- `reports/phase4-heldout-final.json`：原始最终评估；`final_cea_metrics.json`：全部矩阵、分种子/土壤、统计、敏感性与开销。','- `figures/phase4-final/diagram.png` / `.drawio` / `.svg` / `caption.md`：四面板实数图及可编辑源。','- 最终提交和原始大文件SHA索引见 `reports/phase4-final-artifact-registry.json`。','','## 后续工作','','本轮只完成冻结实验，不追加调参。科学下一步是另立新协议检验随机初始氮分布、噪声观测、外部气象/地点与等预算强化学习，并由独立田间验证再讨论应用；不能回用本次留出序列继续选择模型。','']
 path=R/'reports/FINAL_CEA_EXPERIMENTAL_RESULTS.md';path.write_text('\n'.join(lines));print(path)
if __name__=='__main__':main()
